  readonly state: TodosState
  readonly completionError: string | null
  readonly complete: (id: string) => Promise<void>
}

const markDone = (state: TodosState, id: string): TodosState =>
  state.status === 'loaded'
    ? { status: 'loaded', todos: state.todos.map((t) => (t.id === id ? { ...t, status: 'done' } : t)) }
    : state

